using System;
using System.Drawing;
using System.Windows.Forms;
using DevExpress.XtraTab;
using Control;

namespace FamManager.Device
{
    public partial class frmDeviceDetail
    {
        private XtraTabPage tpVehicleInfo;
        private UTextEdit txtOwnerName;
        private UTextEdit txtModel;
        private UTextEdit txtPower;
        private UCalcEdit txtLoadCapacity;
        private UTextEdit txtPlateNo;
        private UTextEdit txtPaintColor;
        private UTextEdit txtChassisNo;
        private UTextEdit txtEngineNo;
        private UCalcEdit txtManufactureYear;
        private UCalcEdit txtInspectionCycleMonth;
        private UCalcEdit txtUsingLengthMonth;
        private DgCheckEdit chkIsRented;
        private UTextEdit txtRentContractNo;
        private UCalcEdit txtMortgageStatusID;

        private void InitVehicleInfoTab()
        {
            if (tpVehicleInfo != null)
                return;

            tpVehicleInfo = new XtraTabPage();
            tpVehicleInfo.Name = "tpVehicleInfo";
            tpVehicleInfo.Text = "Thông tin phương tiện";
            tpVehicleInfo.Size = new Size(1034, 367);

            txtOwnerName = CreateTextField("Tên chủ sở hữu:", 14, 12, 320);
            txtModel = CreateTextField("Model:", 350, 12, 320);
            txtPower = CreateTextField("Công suất:", 686, 12, 320);

            txtLoadCapacity = CreateCalcField("Tải trọng:", 14, 42, 320);
            txtPlateNo = CreateTextField("Biển kiểm soát:", 350, 42, 320);
            txtPaintColor = CreateTextField("Màu sơn:", 686, 42, 320);

            txtChassisNo = CreateTextField("Số khung:", 14, 72, 320);
            txtEngineNo = CreateTextField("Số máy:", 350, 72, 320);
            txtManufactureYear = CreateCalcField("Năm SX:", 686, 72, 320);

            txtInspectionCycleMonth = CreateCalcField("Chu kỳ ĐK (tháng):", 14, 102, 320);
            txtUsingLengthMonth = CreateCalcField("Thời gian SD (tháng):", 350, 102, 320);
            txtMortgageStatusID = CreateCalcField("TT thế chấp:", 686, 102, 320);

            chkIsRented = new DgCheckEdit();
            chkIsRented.Location = new Point(14, 136);
            chkIsRented.Name = "chkIsRented";
            chkIsRented.Properties.Caption = "Cho thuê";
            chkIsRented.Size = new Size(120, 19);
            chkIsRented.TabIndex = 20;

            txtRentContractNo = CreateTextField("HĐ thuê số:", 350, 132, 320);

            tpVehicleInfo.Controls.Add(txtOwnerName);
            tpVehicleInfo.Controls.Add(txtModel);
            tpVehicleInfo.Controls.Add(txtPower);
            tpVehicleInfo.Controls.Add(txtLoadCapacity);
            tpVehicleInfo.Controls.Add(txtPlateNo);
            tpVehicleInfo.Controls.Add(txtPaintColor);
            tpVehicleInfo.Controls.Add(txtChassisNo);
            tpVehicleInfo.Controls.Add(txtEngineNo);
            tpVehicleInfo.Controls.Add(txtManufactureYear);
            tpVehicleInfo.Controls.Add(txtInspectionCycleMonth);
            tpVehicleInfo.Controls.Add(txtUsingLengthMonth);
            tpVehicleInfo.Controls.Add(txtMortgageStatusID);
            tpVehicleInfo.Controls.Add(chkIsRented);
            tpVehicleInfo.Controls.Add(txtRentContractNo);

            TabInformation.TabPages.Add(tpVehicleInfo);
        }

        private UTextEdit CreateTextField(string caption, int left, int top, int width)
        {
            UTextEdit txt = new UTextEdit();
            txt.Caption = caption;
            txt.EditorLeft = 120;
            txt.Location = new Point(left, top);
            txt.Size = new Size(width, 21);
            txt.ReadOnly = false;
            txt.EnterMoveNext = true;
            return txt;
        }

        private UCalcEdit CreateCalcField(string caption, int left, int top, int width)
        {
            UCalcEdit txt = new UCalcEdit();
            txt.Caption = caption;
            txt.EditorLeft = 120;
            txt.Location = new Point(left, top);
            txt.Size = new Size(width, 21);
            txt.ReadOnly = false;
            return txt;
        }

        private void BindVehicleInfoFromObject()
        {
            if (txtOwnerName == null)
                return;

            txtOwnerName.Text = itemDeviceEditing.OwnerName;
            txtModel.Text = itemDeviceEditing.Model;
            txtPower.Text = itemDeviceEditing.Power;
            txtLoadCapacity.EditValue = itemDeviceEditing.LoadCapacity;
            txtPlateNo.Text = itemDeviceEditing.PlateNo;
            txtPaintColor.Text = itemDeviceEditing.PaintColor;
            txtChassisNo.Text = itemDeviceEditing.ChassisNo;
            txtEngineNo.Text = itemDeviceEditing.EngineNo;
            txtManufactureYear.EditValue = itemDeviceEditing.ManufactureYear;
            txtInspectionCycleMonth.EditValue = itemDeviceEditing.InspectionCycleMonth;
            txtUsingLengthMonth.EditValue = itemDeviceEditing.UsingLengthMonth;
            chkIsRented.Checked = itemDeviceEditing.IsRented;
            txtRentContractNo.Text = itemDeviceEditing.RentContractNo;
            txtMortgageStatusID.EditValue = itemDeviceEditing.MortgageStatusID;
        }

        private void BindVehicleInfoToObject()
        {
            if (txtOwnerName == null)
                return;

            itemDeviceEditing.OwnerName = txtOwnerName.TextTrim;
            itemDeviceEditing.Model = txtModel.TextTrim;
            itemDeviceEditing.Power = txtPower.TextTrim;
            itemDeviceEditing.LoadCapacity = txtLoadCapacity.EditValueDecimal;
            itemDeviceEditing.PlateNo = txtPlateNo.TextTrim;
            itemDeviceEditing.PaintColor = txtPaintColor.TextTrim;
            itemDeviceEditing.ChassisNo = txtChassisNo.TextTrim;
            itemDeviceEditing.EngineNo = txtEngineNo.TextTrim;
            itemDeviceEditing.ManufactureYear = txtManufactureYear.EditValueInt32;
            itemDeviceEditing.InspectionCycleMonth = txtInspectionCycleMonth.EditValueInt32;
            itemDeviceEditing.UsingLengthMonth = txtUsingLengthMonth.EditValueInt32;
            itemDeviceEditing.IsRented = chkIsRented.Checked;
            itemDeviceEditing.RentContractNo = txtRentContractNo.TextTrim;
            itemDeviceEditing.MortgageStatusID = txtMortgageStatusID.EditValueInt32;
        }

        private void ResetVehicleInfoControls()
        {
            if (txtOwnerName == null)
                return;

            txtOwnerName.Text = null;
            txtModel.Text = null;
            txtPower.Text = null;
            txtLoadCapacity.EditValue = 0;
            txtPlateNo.Text = null;
            txtPaintColor.Text = null;
            txtChassisNo.Text = null;
            txtEngineNo.Text = null;
            txtManufactureYear.EditValue = 0;
            txtInspectionCycleMonth.EditValue = 0;
            txtUsingLengthMonth.EditValue = 0;
            chkIsRented.Checked = false;
            txtRentContractNo.Text = null;
            txtMortgageStatusID.EditValue = 0;
        }

        private void SyncVehicleFromDevice()
        {
            if (itemDeviceEditing.DeviceID == null)
                return;

            itemDeviceEditing.ExecNonQuery("FAM_Device_SyncVehicle",
                "@DeviceID", itemDeviceEditing.DeviceID,
                "@UpdatedUser", UserSession.Username);
        }
    }
}

