public frmDeviceDetail()
{
    InitializeComponent();
    InitVehicleInfoTab();
    ConfigureDetailFormLayout();
}

private void ConfigureDetailFormLayout()
{
    this.StartPosition = FormStartPosition.CenterScreen;
    this.WindowState = FormWindowState.Maximized;
    this.MaximizeBox = true;
    this.MinimizeBox = true;
}

public void PrepareForAddNew()
{
    ResetData();
    CreateNewCode();
    CheckPermission();
    bolIsOk = false;
    this.Text = "Thêm mới tài sản";
}

public void PrepareForEdit(long deviceID)
{
    LoadData(deviceID);
    this.Text = String.Format("Chi tiết tài sản [{0}]", txtDeviceCode.TextTrim);
}

public void ConfigureEmbeddedMode()
{
    bolIsEmbeddedMode = true;
    this.FormBorderStyle = FormBorderStyle.None;
    this.TopLevel = false;
    this.Dock = DockStyle.Fill;
    this.WindowState = FormWindowState.Normal;
    this.MaximizeBox = false;
    this.MinimizeBox = false;
    btnCancel.Text = "Trở về";
}

private void CloseDetailForm()
{
    if (bolIsEmbeddedMode)
    {
        if (DetailClosed != null)
            DetailClosed(this, EventArgs.Empty);
    }
    else
    {
        this.Close();
    }
}

