private void ShowListView()
{
    if (panelDetailHost != null)
        panelDetailHost.Visible = false;
    dockPanel1.Visibility = DevExpress.XtraBars.Docking.DockVisibility.Visible;
    dockPanel2.Visibility = DevExpress.XtraBars.Docking.DockVisibility.Visible;
    this.Text = "Danh sách tài sản";
}

private void ShowDetailView(long? deviceID)
{
    dockPanel1.Visibility = DevExpress.XtraBars.Docking.DockVisibility.Hidden;
    dockPanel2.Visibility = DevExpress.XtraBars.Docking.DockVisibility.Hidden;
    panelDetailHost.Visible = true;
    panelDetailHost.BringToFront();

    if (frmDetailEmbedded != null)
    {
        panelDetailHost.Controls.Remove(frmDetailEmbedded);
        frmDetailEmbedded.Dispose();
        frmDetailEmbedded = null;
    }

    frmDetailEmbedded = new frmDeviceDetail();
    frmDetailEmbedded.ConfigureEmbeddedMode();
    frmDetailEmbedded.DetailClosed += frmDetailEmbedded_DetailClosed;
    panelDetailHost.Controls.Add(frmDetailEmbedded);

    if (deviceID != null)
        frmDetailEmbedded.PrepareForEdit(deviceID);
    else
        frmDetailEmbedded.PrepareForAddNew();

    frmDetailEmbedded.Show();
    this.Text = deviceID != null ? "Chi tiết tài sản" : "Thêm mới tài sản";
}

private void frmDetailEmbedded_DetailClosed(object sender, EventArgs e)
{
    frmDeviceDetail frm = sender as frmDeviceDetail;
    if (frm != null && frm.IsOk)
    {
        lngDeviceID = frm.DeviceIDSaved;
        new Thread(LoadData).Start();
    }
    ShowListView();
}

