$folder = Get-ChildItem "G:\0.DỰ ÁN\ERP-GiaoThong-DongNai" -Directory | Where-Object { $_.Name -like "m*" } | Select-Object -First 1
$file = Get-ChildItem $folder.FullName -Filter "*.xlsx" | Where-Object { $_.Name -like "Danh*" } | Select-Object -First 1
$out = "G:\0.DỰ ÁN\ERP-GiaoThong-DongNai\Database\Tài sản\phương tiện -lịch trình\_excel_export.json"
$excel = New-Object -ComObject Excel.Application
$excel.Visible = $false
$excel.DisplayAlerts = $false
$wb = $excel.Workbooks.Open($file.FullName)
$ws = $wb.Worksheets.Item(1)
$used = $ws.UsedRange
$rows = $used.Rows.Count
$cols = $used.Columns.Count
$data = @()
for ($r = 5; $r -le $rows; $r++) {
  $obj = [ordered]@{}
  for ($c = 1; $c -le $cols; $c++) {
    $h = $ws.Cells.Item(4,$c).Text
    if ([string]::IsNullOrWhiteSpace($h)) { $h = "Col$c" }
    $v = $ws.Cells.Item($r,$c).Text
    if ($null -eq $v) { $v = '' }
    $obj[$h] = $v
  }
  $code = $obj['Ma tài sản']
  if ([string]::IsNullOrWhiteSpace($code)) { $code = $obj.Values[0] }
  if (-not [string]::IsNullOrWhiteSpace($code) -or -not [string]::IsNullOrWhiteSpace($obj.Values[1])) {
    $data += [pscustomobject]$obj
  }
}
$data | ConvertTo-Json -Depth 5 | Out-File -FilePath $out -Encoding UTF8
Write-Host "Exported $($data.Count) rows to $out"
$wb.Close($false)
$excel.Quit()
[GC]::Collect()

