public bool LoadData(long? deviceID)
{
    try
    {
        if (lookupDeviceStatusID.DataSource == null)
            LoadReferenceData();// load trước nếu chưa từng load, chứ nó gán không vô

        lngDeviceID = deviceID;

        if (lngDeviceID == null)
            return true;

        itemDeviceEditing = new FAM_Device();
        itemDeviceEditing.DeviceID = lngDeviceID;
        if (!itemDeviceEditing.Get())
        {
            string strError = "Không tải được thông tin tài sản.";
            if (itemDeviceEditing.ErrorException != null)
                strError += " " + itemDeviceEditing.ErrorException.Message;
            ErrorManager.Error(strError);
            return false;
        }
        // gán giá trị vào form   
        //nhóm thông tin cơ bản
        txtDeviceCode.Text = itemDeviceEditing.DeviceCode;
        txtDeviceCode2.Text = itemDeviceEditing.DeviceCode2;
        txtDeviceName.Text = itemDeviceEditing.DeviceName;

        lookupDeviceKindID.EditValue = itemDeviceEditing.DeviceKindID;
        lookupDeviceStatusID.EditValue = itemDeviceEditing.DeviceStatusID;
        //lookupParentDeviceID.EditValue = itemDeviceEditing.ParentDeviceID;

        txtQuantity.EditValue = itemDeviceEditing.Quantity;
        txtPrice.EditValue = itemDeviceEditing.Price;
        txtRemainPrice.EditValue = itemDeviceEditing.RemainPrice;

        uUsingLength.EditValue = itemDeviceEditing.UsingLength;
        uOffice.EditValue = itemDeviceEditing.OfficeID;
        lookupPlaceID.EditValue = itemDeviceEditing.PlaceID;
        if (itemDeviceEditing.UsingEmployeeID != null && itemDeviceEditing.UsingEmployeeID > 0)
            lookupUsingEmployeeID.EditValue = itemDeviceEditing.UsingEmployeeID;
        else
            lookupUsingEmployeeID.EditValue = null;
        lookupUnitID.EditValue = itemDeviceEditing.UnitID;

        txtDepValue.EditValue = itemDeviceEditing.DepValue;
        txtDepPercent.EditValue = itemDeviceEditing.DepPercent;
        rdoIsLineDep.Checked = itemDeviceEditing.IsLineDep;

        dtmInputVoucherDate.EditValue = itemDeviceEditing.InputVoucherDate;
        txtInputVoucherCode.Text = itemDeviceEditing.InputVoucherCode;
        txtLabelNo.Text = itemDeviceEditing.LabelNo;
        txtMadeIn.Text = itemDeviceEditing.MadeIn;
        txtSupplier.Text = itemDeviceEditing.Supplier;
        txtUsingFor.Text = itemDeviceEditing.UsingFor;

        dtmUsingDate.EditValue = itemDeviceEditing.UsingDate;
        dtmWarrantyExpired.EditValue = itemDeviceEditing.WarrantyExpired;
        txtTechInfo.EditValue = itemDeviceEditing.TechInfo;

        lookupCostSourceID.EditValue = itemDeviceEditing.CostSourceID; // nguồn tài sản

        if (itemDeviceEditing.GroupOneID == null || itemDeviceEditing.GroupOneID == 0)
            lookupGroupOneID.EditValue = 1;
        else
            lookupGroupOneID.EditValue = itemDeviceEditing.GroupOneID; // cơ quan quản lý
        if (itemDeviceEditing.GroupTwoID == null || itemDeviceEditing.GroupTwoID == 0)
            lookupGroupTwoID.EditValue = null;
        else
            lookupGroupTwoID.EditValue = itemDeviceEditing.GroupTwoID; // độ bền

        BindVehicleInfoFromObject();

        // này là gì mà sao đặt tên và kiểu dữ liệu ngộ thế (đang nhóm Status 1 đến 7  là int, nên làm cột khác đi chứ)
        //dgCheckKiemKe.Checked = itemDeviceEditing.Status6;

        bolIsEditing = true;
        txtDeviceCode.Focus();
        uImage.ObjectID = lngDeviceID;
        uImage.LoadData(); // load hình cho sinh viên (nếu có)

        LoadDetail(lngDeviceID); // tải chi tiết
        CheckPermission();
        return true;
    }
    catch (Exception objEx)
    {
        ErrorManager.Error("Lỗi khi mở chi tiết tài sản: " + objEx.Message);
        return false;
    }
}

