private void OpenDeviceDetail(long? deviceID)
{
    frmDeviceDetail frmEdit = new frmDeviceDetail();
    if (deviceID != null)
    {
        if (!frmEdit.LoadData(deviceID))
            return;
    }
    frmEdit.ShowDialog();
    if (frmEdit.IsOk)
    {
        lngDeviceID = frmEdit.DeviceIDSaved;
        btnSearch_Click(null, null);
    }
}

